-- PARI initial schema. Mirrors the ERD in docs/diagrams/erd-backend.md.
-- Conventions: uuid keys generated by the application, timestamptz in UTC,
-- money as bigint minor units (grosze), enums as varchar + CHECK.

CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ---------------------------------------------------------------- users

CREATE TABLE users (
    id              uuid         PRIMARY KEY,
    email           varchar(255) NOT NULL,
    password_hash   varchar(255) NOT NULL,
    first_name      varchar(100) NOT NULL,
    last_name       varchar(100) NOT NULL,
    phone_enc       varchar(512),                       -- AES-256-GCM, base64 (NF04)
    email_verified  boolean      NOT NULL DEFAULT false,
    phone_verified  boolean      NOT NULL DEFAULT false,
    status          varchar(20)  NOT NULL DEFAULT 'ACTIVE'
                    CHECK (status IN ('ACTIVE', 'BLOCKED')),
    active_role     varchar(20)  NOT NULL DEFAULT 'DRIVER'
                    CHECK (active_role IN ('DRIVER', 'OWNER', 'VERIFIER', 'SUPPORT', 'ADMIN')),
    loyalty_points  integer      NOT NULL DEFAULT 0 CHECK (loyalty_points >= 0),
    created_at      timestamptz  NOT NULL DEFAULT now(),
    updated_at      timestamptz  NOT NULL DEFAULT now(),
    version         bigint       NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX users_email_lower_uq ON users (lower(email));

CREATE TABLE user_roles (
    user_id uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role    varchar(20) NOT NULL CHECK (role IN ('DRIVER', 'OWNER', 'VERIFIER', 'SUPPORT', 'ADMIN')),
    PRIMARY KEY (user_id, role)
);

CREATE TABLE auth_tokens (
    id          uuid         PRIMARY KEY,
    user_id     uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    type        varchar(20)  NOT NULL
                CHECK (type IN ('REFRESH', 'EMAIL_VERIFY', 'PHONE_CODE', 'PASSWORD_RESET')),
    token_hash  varchar(255) NOT NULL,
    expires_at  timestamptz  NOT NULL,
    used_at     timestamptz,
    created_at  timestamptz  NOT NULL DEFAULT now(),
    updated_at  timestamptz  NOT NULL DEFAULT now(),
    version     bigint       NOT NULL DEFAULT 0
);
CREATE INDEX auth_tokens_lookup_idx ON auth_tokens (type, token_hash);
CREATE INDEX auth_tokens_user_idx ON auth_tokens (user_id);

CREATE TABLE vehicles (
    id            uuid         PRIMARY KEY,
    user_id       uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    model         varchar(100) NOT NULL,
    plate_number  varchar(20)  NOT NULL,
    created_at    timestamptz  NOT NULL DEFAULT now(),
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    version       bigint       NOT NULL DEFAULT 0
);
CREATE INDEX vehicles_user_idx ON vehicles (user_id);

CREATE TABLE payment_methods (
    id            uuid         PRIMARY KEY,
    user_id       uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    provider_ref  varchar(255) NOT NULL,                -- Stripe pm_...
    brand         varchar(30)  NOT NULL,
    last4         varchar(4)   NOT NULL,
    exp_month     integer      NOT NULL CHECK (exp_month BETWEEN 1 AND 12),
    exp_year      integer      NOT NULL,
    is_default    boolean      NOT NULL DEFAULT false,
    created_at    timestamptz  NOT NULL DEFAULT now(),
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    version       bigint       NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX payment_methods_provider_uq ON payment_methods (provider_ref);
CREATE INDEX payment_methods_user_idx ON payment_methods (user_id);

-- ---------------------------------------------------------------- spots

CREATE TABLE parking_spots (
    id                      uuid          PRIMARY KEY,
    owner_id                uuid          NOT NULL REFERENCES users (id),
    name                    varchar(150)  NOT NULL,
    description             text,
    street                  varchar(200)  NOT NULL,
    city                    varchar(100)  NOT NULL,
    postal_code             varchar(20)   NOT NULL,
    country                 varchar(2)    NOT NULL DEFAULT 'PL',
    lat                     double precision NOT NULL CHECK (lat BETWEEN -90 AND 90),
    lng                     double precision NOT NULL CHECK (lng BETWEEN -180 AND 180),
    -- derived from lat/lng; used by ST_DWithin searches (F11, F12)
    location                geography(Point, 4326) GENERATED ALWAYS AS
                            (ST_SetSRID(ST_MakePoint(lng, lat), 4326)::geography) STORED,
    length_cm               integer       NOT NULL CHECK (length_cm > 0),
    width_cm                integer       NOT NULL CHECK (width_cm > 0),
    height_cm               integer       CHECK (height_cm > 0),
    hourly_price_minor      bigint        NOT NULL CHECK (hourly_price_minor >= 0),
    currency                varchar(3)    NOT NULL DEFAULT 'PLN',
    access_instructions     text,
    auto_accept             boolean       NOT NULL DEFAULT true,
    realtime_status_enabled boolean       NOT NULL DEFAULT false,
    occupancy               varchar(20)   NOT NULL DEFAULT 'FREE' CHECK (occupancy IN ('FREE', 'OCCUPIED')),
    status                  varchar(20)   NOT NULL DEFAULT 'DRAFT'
                            CHECK (status IN ('DRAFT', 'ACTIVE', 'INACTIVE', 'BLOCKED')),
    is_verified             boolean       NOT NULL DEFAULT false,
    ownership_declared_at   timestamptz,
    avg_rating              numeric(3, 2) NOT NULL DEFAULT 0,
    review_count            integer       NOT NULL DEFAULT 0,
    created_at              timestamptz   NOT NULL DEFAULT now(),
    updated_at              timestamptz   NOT NULL DEFAULT now(),
    version                 bigint        NOT NULL DEFAULT 0,
    -- F09: a listing can only be active after the owner confirmed the right to dispose of the space
    CONSTRAINT parking_spots_active_requires_declaration
        CHECK (status <> 'ACTIVE' OR ownership_declared_at IS NOT NULL)
);
CREATE INDEX parking_spots_location_gist ON parking_spots USING gist (location);
CREATE INDEX parking_spots_owner_idx ON parking_spots (owner_id);
CREATE INDEX parking_spots_status_price_idx ON parking_spots (status, hourly_price_minor);

CREATE TABLE spot_photos (
    id           uuid         PRIMARY KEY,
    spot_id      uuid         NOT NULL REFERENCES parking_spots (id) ON DELETE CASCADE,
    storage_key  varchar(500) NOT NULL,
    position     integer      NOT NULL DEFAULT 0,
    created_at   timestamptz  NOT NULL DEFAULT now(),
    updated_at   timestamptz  NOT NULL DEFAULT now(),
    version      bigint       NOT NULL DEFAULT 0
);
CREATE INDEX spot_photos_spot_idx ON spot_photos (spot_id, position);

CREATE TABLE amenities (
    id          uuid         PRIMARY KEY,
    code        varchar(50)  NOT NULL UNIQUE,
    label       varchar(100) NOT NULL,
    created_at  timestamptz  NOT NULL DEFAULT now(),
    updated_at  timestamptz  NOT NULL DEFAULT now(),
    version     bigint       NOT NULL DEFAULT 0
);

CREATE TABLE spot_amenities (
    spot_id     uuid NOT NULL REFERENCES parking_spots (id) ON DELETE CASCADE,
    amenity_id  uuid NOT NULL REFERENCES amenities (id),
    PRIMARY KEY (spot_id, amenity_id)
);

-- ---------------------------------------------------------------- availability

CREATE TABLE availability_rules (
    id           uuid        PRIMARY KEY,
    spot_id      uuid        NOT NULL REFERENCES parking_spots (id) ON DELETE CASCADE,
    day_of_week  integer     NOT NULL CHECK (day_of_week BETWEEN 1 AND 7),   -- ISO: 1 = Monday
    start_time   time        NOT NULL,
    end_time     time        NOT NULL,
    valid_from   date,
    valid_to     date,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    version      bigint      NOT NULL DEFAULT 0,
    CHECK (end_time > start_time),
    CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from)
);
CREATE INDEX availability_rules_spot_idx ON availability_rules (spot_id, day_of_week);

CREATE TABLE availability_exceptions (
    id          uuid         PRIMARY KEY,
    spot_id     uuid         NOT NULL REFERENCES parking_spots (id) ON DELETE CASCADE,
    starts_at   timestamptz  NOT NULL,
    ends_at     timestamptz  NOT NULL,
    kind        varchar(10)  NOT NULL CHECK (kind IN ('BLOCKED', 'OPEN')),
    reason      varchar(255),
    created_at  timestamptz  NOT NULL DEFAULT now(),
    updated_at  timestamptz  NOT NULL DEFAULT now(),
    version     bigint       NOT NULL DEFAULT 0,
    CHECK (ends_at > starts_at)
);
CREATE INDEX availability_exceptions_spot_idx ON availability_exceptions (spot_id, starts_at);

-- ---------------------------------------------------------------- reservations

CREATE TABLE reservations (
    id                      uuid         PRIMARY KEY,
    code                    varchar(30)  NOT NULL UNIQUE,                 -- RSV-...
    spot_id                 uuid         NOT NULL REFERENCES parking_spots (id),
    driver_id               uuid         NOT NULL REFERENCES users (id),
    vehicle_id              uuid         NOT NULL REFERENCES vehicles (id),
    starts_at               timestamptz  NOT NULL,
    ends_at                 timestamptz  NOT NULL,
    status                  varchar(20)  NOT NULL
                            CHECK (status IN ('PENDING_PAYMENT', 'PENDING_APPROVAL', 'CONFIRMED',
                                              'IN_PROGRESS', 'COMPLETED', 'CANCELLED', 'REJECTED')),
    hourly_rate_minor       bigint       NOT NULL CHECK (hourly_rate_minor >= 0),   -- snapshot at booking time
    spot_cost_minor         bigint       NOT NULL CHECK (spot_cost_minor >= 0),
    service_fee_minor       bigint       NOT NULL CHECK (service_fee_minor >= 0),
    total_minor             bigint       NOT NULL CHECK (total_minor >= 0),
    commission_minor        bigint       NOT NULL CHECK (commission_minor >= 0),    -- F18
    pin_code                varchar(10),
    qr_token                varchar(100),
    check_in_at             timestamptz,
    check_out_at            timestamptz,
    overstay_penalty_minor  bigint       CHECK (overstay_penalty_minor >= 0),       -- F19
    final_cost_minor        bigint       CHECK (final_cost_minor >= 0),
    cancel_reason           varchar(500),
    cancelled_at            timestamptz,
    created_at              timestamptz  NOT NULL DEFAULT now(),
    updated_at              timestamptz  NOT NULL DEFAULT now(),
    version                 bigint       NOT NULL DEFAULT 0,
    CHECK (ends_at > starts_at),
    -- A space can never be booked twice for overlapping times (F13).
    -- Every status that still holds the slot takes part; PENDING_PAYMENT holds it
    -- until the payment times out, so two drivers cannot pay for the same slot.
    CONSTRAINT reservations_no_overlap
        EXCLUDE USING gist (spot_id WITH =, tstzrange(starts_at, ends_at, '[)') WITH &&)
        WHERE (status IN ('PENDING_PAYMENT', 'PENDING_APPROVAL', 'CONFIRMED', 'IN_PROGRESS'))
);
CREATE INDEX reservations_driver_idx ON reservations (driver_id, status);
CREATE INDEX reservations_spot_idx ON reservations (spot_id, starts_at);
CREATE INDEX reservations_status_idx ON reservations (status, ends_at);

CREATE TABLE payments (
    id              uuid         PRIMARY KEY,
    reservation_id  uuid         NOT NULL REFERENCES reservations (id),
    type            varchar(10)  NOT NULL CHECK (type IN ('CHARGE', 'PENALTY', 'REFUND')),
    provider_ref    varchar(255),                                   -- Stripe pi_ / re_
    amount_minor    bigint       NOT NULL CHECK (amount_minor >= 0),
    currency        varchar(3)   NOT NULL DEFAULT 'PLN',
    status          varchar(10)  NOT NULL CHECK (status IN ('PENDING', 'SUCCEEDED', 'FAILED')),
    created_at      timestamptz  NOT NULL DEFAULT now(),
    updated_at      timestamptz  NOT NULL DEFAULT now(),
    version         bigint       NOT NULL DEFAULT 0
);
-- a repeated provider webhook cannot create a second row (idempotency)
CREATE UNIQUE INDEX payments_provider_ref_uq ON payments (provider_ref) WHERE provider_ref IS NOT NULL;
CREATE INDEX payments_reservation_idx ON payments (reservation_id);

CREATE TABLE payouts (
    id                uuid         PRIMARY KEY,
    reservation_id    uuid         NOT NULL UNIQUE REFERENCES reservations (id),
    owner_id          uuid         NOT NULL REFERENCES users (id),
    gross_minor       bigint       NOT NULL CHECK (gross_minor >= 0),
    commission_minor  bigint       NOT NULL CHECK (commission_minor >= 0),
    net_minor         bigint       NOT NULL CHECK (net_minor >= 0),
    status            varchar(10)  NOT NULL CHECK (status IN ('SCHEDULED', 'HELD', 'PAID', 'CANCELLED')),
    release_at        timestamptz  NOT NULL,                        -- ends_at + 24 h (F17)
    paid_at           timestamptz,
    provider_ref      varchar(255),
    created_at        timestamptz  NOT NULL DEFAULT now(),
    updated_at        timestamptz  NOT NULL DEFAULT now(),
    version           bigint       NOT NULL DEFAULT 0,
    CHECK (net_minor = gross_minor - commission_minor)
);
CREATE INDEX payouts_due_idx ON payouts (status, release_at);
CREATE INDEX payouts_owner_idx ON payouts (owner_id, status);

-- ---------------------------------------------------------------- reviews

CREATE TABLE reviews (
    id              uuid         PRIMARY KEY,
    reservation_id  uuid         NOT NULL REFERENCES reservations (id),
    author_id       uuid         NOT NULL REFERENCES users (id),
    reviewee_id     uuid         NOT NULL REFERENCES users (id),
    spot_id         uuid         REFERENCES parking_spots (id),     -- set when a driver rates the spot
    rating          integer      NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment         text,
    status          varchar(10)  NOT NULL DEFAULT 'VISIBLE' CHECK (status IN ('VISIBLE', 'HIDDEN')),
    created_at      timestamptz  NOT NULL DEFAULT now(),
    updated_at      timestamptz  NOT NULL DEFAULT now(),
    version         bigint       NOT NULL DEFAULT 0,
    UNIQUE (reservation_id, author_id)
);
CREATE INDEX reviews_spot_idx ON reviews (spot_id, status);
CREATE INDEX reviews_reviewee_idx ON reviews (reviewee_id);

-- ---------------------------------------------------------------- support and verification

CREATE TABLE reports (
    id                uuid         PRIMARY KEY,
    reservation_id    uuid         NOT NULL REFERENCES reservations (id),
    reporter_id       uuid         NOT NULL REFERENCES users (id),
    reported_user_id  uuid         REFERENCES users (id),
    category          varchar(50)  NOT NULL,
    description       text         NOT NULL,
    status            varchar(15)  NOT NULL DEFAULT 'OPEN'
                      CHECK (status IN ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'CLOSED')),
    assigned_to       uuid         REFERENCES users (id),           -- support user
    resolution        text,
    closed_at         timestamptz,
    created_at        timestamptz  NOT NULL DEFAULT now(),
    updated_at        timestamptz  NOT NULL DEFAULT now(),
    version           bigint       NOT NULL DEFAULT 0
);
CREATE INDEX reports_status_idx ON reports (status, assigned_to);
CREATE INDEX reports_reservation_idx ON reports (reservation_id);

CREATE TABLE report_messages (
    id             uuid        PRIMARY KEY,
    report_id      uuid        NOT NULL REFERENCES reports (id) ON DELETE CASCADE,
    author_id      uuid        NOT NULL REFERENCES users (id),
    body           text        NOT NULL,
    internal_note  boolean     NOT NULL DEFAULT false,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    version        bigint      NOT NULL DEFAULT 0
);
CREATE INDEX report_messages_report_idx ON report_messages (report_id, created_at);

CREATE TABLE sanctions (
    id          uuid         PRIMARY KEY,
    user_id     uuid         NOT NULL REFERENCES users (id),
    report_id   uuid         REFERENCES reports (id),
    issued_by   uuid         NOT NULL REFERENCES users (id),
    type        varchar(10)  NOT NULL CHECK (type IN ('WARNING', 'BLOCK', 'UNBLOCK')),
    reason      text         NOT NULL,
    created_at  timestamptz  NOT NULL DEFAULT now(),
    updated_at  timestamptz  NOT NULL DEFAULT now(),
    version     bigint       NOT NULL DEFAULT 0
);
CREATE INDEX sanctions_user_idx ON sanctions (user_id, type);

CREATE TABLE verification_requests (
    id                uuid         PRIMARY KEY,
    spot_id           uuid         NOT NULL REFERENCES parking_spots (id),
    requested_by      uuid         NOT NULL REFERENCES users (id),
    verifier_id       uuid         REFERENCES users (id),
    status            varchar(15)  NOT NULL DEFAULT 'REQUESTED'
                      CHECK (status IN ('REQUESTED', 'ASSIGNED', 'APPROVED', 'REJECTED')),
    rejection_reason  text,                                          -- F25
    notes             text,
    requested_at      timestamptz  NOT NULL DEFAULT now(),
    decided_at        timestamptz,
    created_at        timestamptz  NOT NULL DEFAULT now(),
    updated_at        timestamptz  NOT NULL DEFAULT now(),
    version           bigint       NOT NULL DEFAULT 0,
    CHECK (status <> 'REJECTED' OR rejection_reason IS NOT NULL)
);
CREATE INDEX verification_requests_queue_idx ON verification_requests (status, requested_at);
CREATE INDEX verification_requests_spot_idx ON verification_requests (spot_id);

-- ---------------------------------------------------------------- notifications, premium

CREATE TABLE notifications (
    id          uuid         PRIMARY KEY,
    user_id     uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    type        varchar(50)  NOT NULL,
    title       varchar(200) NOT NULL,
    body        text,
    payload     jsonb,
    channel     varchar(10)  NOT NULL CHECK (channel IN ('IN_APP', 'EMAIL', 'PUSH')),
    read_at     timestamptz,
    sent_at     timestamptz,
    created_at  timestamptz  NOT NULL DEFAULT now(),
    updated_at  timestamptz  NOT NULL DEFAULT now(),
    version     bigint       NOT NULL DEFAULT 0
);
CREATE INDEX notifications_user_idx ON notifications (user_id, read_at);

CREATE TABLE premium_subscriptions (
    id            uuid         PRIMARY KEY,
    owner_id      uuid         NOT NULL REFERENCES users (id),
    plan          varchar(30)  NOT NULL,
    status        varchar(10)  NOT NULL CHECK (status IN ('ACTIVE', 'CANCELLED', 'EXPIRED')),
    started_at    timestamptz  NOT NULL,
    expires_at    timestamptz  NOT NULL,
    provider_ref  varchar(255),
    created_at    timestamptz  NOT NULL DEFAULT now(),
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    version       bigint       NOT NULL DEFAULT 0,
    CHECK (expires_at > started_at)
);
CREATE INDEX premium_subscriptions_owner_idx ON premium_subscriptions (owner_id, status, expires_at);

-- ---------------------------------------------------------------- audit and settings

-- NF05: immutable record of financial and reservation operations
CREATE TABLE audit_log (
    id           bigint       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    actor_id     uuid         REFERENCES users (id),                 -- null for system actions
    entity_type  varchar(50)  NOT NULL,
    entity_id    uuid,
    action       varchar(50)  NOT NULL,
    data         jsonb,
    created_at   timestamptz  NOT NULL DEFAULT now()
);
CREATE INDEX audit_log_entity_idx ON audit_log (entity_type, entity_id);
CREATE INDEX audit_log_actor_idx ON audit_log (actor_id, created_at);

CREATE FUNCTION audit_log_reject_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_log is append-only (% not allowed)', TG_OP;
END;
$$;
CREATE TRIGGER audit_log_no_update_delete
    BEFORE UPDATE OR DELETE ON audit_log
    FOR EACH ROW EXECUTE FUNCTION audit_log_reject_change();
CREATE TRIGGER audit_log_no_truncate
    BEFORE TRUNCATE ON audit_log
    FOR EACH STATEMENT EXECUTE FUNCTION audit_log_reject_change();

CREATE TABLE platform_settings (
    setting_key    varchar(100) PRIMARY KEY,
    setting_value  varchar(255) NOT NULL,
    description    varchar(255),
    updated_at     timestamptz  NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------- seed data

